// ═══════════════════════════════════════════════════════════════════════
//  THE COST BOUNDARY. Everything above this node is free; everything below
//  spends an agentic turn. On a healthy host this returns [] and the branch
//  stops — which is what happens on the overwhelming majority of runs.
// ═══════════════════════════════════════════════════════════════════════
//
//  There is deliberately NO threshold logic here. The probe already decided,
//  on the host, whether this is an edge worth waking Orion for — escalation,
//  recovery, or a once-a-day nudge that an unhealthy box is still unhealthy.
//  Re-deciding it here would put a second, divergent copy of the thresholds
//  in n8n, where nothing tests it.

const res = $input.first().json || {};
const store = $getWorkflowStaticData('global');

if (res.status === 'disabled') {
  // LIFEBOAT_PROTOCOL_ENABLED is off on this deployment. Nothing to do, and
  // nothing to complain about every fifteen minutes.
  return [];
}

if (res.status === 'error') {
  // The host could not be read. Do NOT wake an agent for this on every poll:
  // an unreachable box is usually unreachable for a reason already producing
  // its own alarms, and 96 pushes a day would bury it. EDGE-triggered — one
  // push when the probe starts failing, one when it recovers.
  if (store.probeBroken) return [];
  store.probeBroken = true;
  return [{ json: {
    alert: true,
    level: '',
    intent: 'The Lifeboat watchdog cannot read the host right now (' +
      (res.detail || 'no detail') + '). Tell the owner in ONE short line that ' +
      'the resource watch is blind and the system_ops host bridge probably ' +
      'needs looking at. Do not call any tool.'
  }}];
}

store.probeBroken = false;

if (!res.changed) return [];

// What Orion is being woken up to DO. Four different situations; wording them
// identically is how a "the host recovered" push arrives sounding like a fire.
let intent;
if (res.reason === 'recovered') {
  intent = 'The host is back to healthy. Tell the owner in ONE line with the ' +
    'numbers (' + res.summary + '). Do not run any reclamation and do not ' +
    'write a report.';
} else if (res.level === 'critical') {
  intent = 'The host is CRITICAL: ' + res.summary + '. Run ' +
    'lifeboat_protocol(action="bail") NOW — Tier 1 only, it deletes nothing ' +
    'that was not already garbage — then push the owner ONE message saying ' +
    'that you ran it unasked, what it reclaimed, and what is still pressed. ' +
    'Do NOT jettison the arsenal: if Tier 1 was not enough, give him the ' +
    'numbers and what Tier 2 costs and let him decide.';
} else if (res.reason === 'still_unhealthy') {
  intent = 'The host has been under resource pressure for a while and nobody ' +
    'has fixed it: ' + res.summary + '. Remind the owner in one short message ' +
    'with the numbers and the recommendation (' + res.recommendation + '). Do ' +
    'NOT reclaim anything — he has already been told once and has not asked ' +
    'you to act.';
} else {
  intent = 'The host has crossed into resource pressure: ' + res.summary +
    '. Tell the owner, with the numbers and what you propose (' +
    res.recommendation + '), and ASK before reclaiming anything. Do NOT call ' +
    'lifeboat_protocol with any action other than assess.';
}

return [{ json: Object.assign({}, res, { intent: intent }) }];
